import type { GoalType, MealSource, MealType } from './schemas/enums.ts';

/**
 * Achievement catalog, built from metrics × tiers (~120 achievements). Titles/descriptions live in
 * i18n under `achievements.metrics.<metric>` and take `{{count}}`.
 *
 * Health note: weight achievements count progress *towards the user's own goal* (safeguarded by
 * computeGoalPlan); there is no achievement for eating less or for fast weight loss.
 */
export const ACHIEVEMENT_CATEGORIES = [
  'consistency',
  'logging',
  'nutrition',
  'body',
  'kitchen',
  'exploration',
] as const;
export type AchievementCategory = (typeof ACHIEVEMENT_CATEGORIES)[number];

